package com.grifplot.libros;
import android.app.*;import android.view.*;import android.widget.*;import android.text.*;import android.graphics.*;import android.graphics.drawable.*;
/** All letters and digits on one page; square keys and compact actions. */
final class LargeKeyboard {
 static void bind(MainActivity a,EditText field,Runnable accept,boolean numeric){field.setShowSoftInputOnFocus(false);field.setOnClickListener(v->show(a,field,accept,numeric));field.setSelectAllOnFocus(false);}
 static void openOnEntry(MainActivity a,EditText field,Runnable accept){final int token=a.generation;field.post(()->{if(token==a.generation&&!a.isFinishing()&&!a.isDestroyed()&&field.isAttachedToWindow()&&field.isShown()){show(a,field,accept,false);a.touch();}});}
 static Button control(MainActivity a,String title,View.OnClickListener click){Button b=a.button(title,click,false);b.setTextSize(18);b.setMinHeight(0);b.setMinimumHeight(0);b.setPadding(a.dp(3),0,a.dp(3),0);return b;}
 static LinearLayout.LayoutParams controlSize(MainActivity a,float weight){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,weight);p.setMargins(a.dp(3),a.dp(3),a.dp(3),a.dp(3));return p;}
 static void show(MainActivity a,EditText target,Runnable accept,boolean numeric){
  if(a.keyboard!=null&&a.keyboard.isShowing())return;a.hideKeyboard();android.util.DisplayMetrics dm=a.getResources().getDisplayMetrics();int width=(int)(dm.widthPixels*.98),height=(int)(dm.heightPixels*.96);int header=Math.max(a.dp(60),Math.min(a.dp(100),height/9));
  LinearLayout body=a.column();body.setPadding(a.dp(6),a.dp(6),a.dp(6),a.dp(6));body.setBackgroundColor(MainActivity.BG);
  EditText text=new EditText(a);text.setShowSoftInputOnFocus(false);text.setSingleLine(true);text.setTextSize(30);text.setText(target.getText());text.setHint(target.getHint());text.setPadding(a.dp(16),a.dp(8),a.dp(16),a.dp(8));text.setBackground(a.box(Color.WHITE,0xFFD5D0C9));body.addView(text,new LinearLayout.LayoutParams(-1,header));
  LinearLayout keys=a.column();keys.setGravity(Gravity.CENTER);body.addView(keys,new LinearLayout.LayoutParams(-1,0,1));Runnable[] draw={null};draw[0]=()->{
   keys.removeAllViews();int columns=width>=height?10:6;String letters="1234567890qwertyuiopasdfghjklñzxcvbnmáéíóúü";String[] rows;
   if(columns==10)rows=new String[]{"1234567890","qwertyuiop","asdfghjklñ","zxcvbnm","áéíóúü"};else{rows=new String[(letters.length()+columns-1)/columns];for(int i=0;i<rows.length;i++)rows[i]=letters.substring(i*columns,Math.min(letters.length(),(i+1)*columns));}
   int usableWidth=keys.getWidth()>0?keys.getWidth():width-a.dp(12),usableHeight=keys.getHeight()>0?keys.getHeight():height-header-a.dp(124);int unit=Math.min(usableWidth/columns,usableHeight/rows.length);int gap=Math.max(1,Math.min(a.dp(3),unit/14)),side=Math.max(1,unit-2*gap);float font=Math.max(26,Math.min(80,side/dm.scaledDensity*.66f));
   for(String row:rows){LinearLayout line=a.row();line.setGravity(Gravity.CENTER);for(int i=0;i<row.length();i++){String label=String.valueOf(row.charAt(i));final String letter=label;Button key=control(a,label.toUpperCase(java.util.Locale.ROOT),v->insert(text,letter));key.setTextSize(font);key.setTypeface(Typeface.DEFAULT,Typeface.BOLD);key.setIncludeFontPadding(false);key.setPadding(0,0,0,0);GradientDrawable square=new GradientDrawable();square.setColor(Color.WHITE);square.setCornerRadius(0);square.setStroke(a.dp(1),0xFFD5D0C9);key.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf(0x22000000),square,null));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(side,side);p.setMargins(gap,gap,gap,gap);line.addView(key,p);}keys.addView(line,new LinearLayout.LayoutParams(-1,unit));}
  };keys.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{if(r-l!=or-ol||b-t!=ob-ot)draw[0].run();});draw[0].run();
  LinearLayout options=a.row();options.addView(control(a,"Espacio",v->insert(text," ")),controlSize(a,2));options.addView(control(a,"Borrar ⌫",v->erase(text)),controlSize(a,1));if(numeric)options.addView(control(a,"Decimal .",v->insert(text,".")),controlSize(a,1));body.addView(options,new LinearLayout.LayoutParams(-1,a.dp(50)));
  LinearLayout bottom=a.row();bottom.addView(control(a,"Borrar todo",v->text.setText("")),controlSize(a,1));bottom.addView(control(a,"Cancelar",v->{if(a.keyboard!=null)a.keyboard.dismiss();}),controlSize(a,1));Button done=control(a,accept==null?"Listo":"Buscar",v->{target.setText(text.getText());target.setSelection(target.length());a.keyboard.dismiss();a.touch();if(accept!=null)accept.run();});done.setTextColor(Color.WHITE);done.setBackground(a.box(MainActivity.RED,0));bottom.addView(done,controlSize(a,1));body.addView(bottom,new LinearLayout.LayoutParams(-1,a.dp(54)));
  Dialog dialog=new Dialog(a);a.keyboard=dialog;dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);dialog.setContentView(body);Window window=dialog.getWindow();window.setBackgroundDrawableResource(android.R.color.transparent);window.addFlags(WindowManager.LayoutParams.FLAG_ALT_FOCUSABLE_IM);dialog.setOnDismissListener(d->{target.clearFocus();if(a.keyboard==dialog)a.keyboard=null;a.immersive();});dialog.show();window.setLayout(width,height);window.getDecorView().setSystemUiVisibility(a.getWindow().getDecorView().getSystemUiVisibility());text.requestFocus();text.setSelection(text.length());
 }
 static void insert(EditText field,String value){int s=Math.max(0,field.getSelectionStart()),e=Math.max(s,field.getSelectionEnd());field.getText().replace(s,e,value);}
 static void erase(EditText field){int s=Math.max(0,field.getSelectionStart()),e=Math.max(s,field.getSelectionEnd());if(s==e&&s>0)s=Character.offsetByCodePoints(field.getText(),s,-1);field.getText().delete(s,e);}
}
